window.flightAirspaceReview=()=>{const {v,ready}=results(),issues=[];if(Number.isFinite(v.flightStart)&&Number.isFinite(v.end)&&(v.flightStart<v.start||v.flightStart>=v.end))issues.push('Airspace: this take-off lies outside the reviewed site session. Extend/review the session or start a new one.');if(el('airspacepermissionstate').value!=='resolved')issues.push('Airspace: restrictions/permissions have not been resolved.');if(v.invalid||v.windowStart===null)issues.push('Airspace: enter a valid session end after the selected start.');if(!site)issues.push('Airspace: select the launch site for the search area.');else if(!ready)issues.push('Airspace: set the full mission-area radius (1–5000 m).');if(!el('airspacereviewed').checked||reviewedSignature!==signature())issues.push('Airspace: review mapped overlaps, NOTAM candidates/unlocated notices and record a current official briefing reference.');if(!el('briefingref').value.trim())issues.push('Airspace: add official briefing time/reference and permissions or follow-up actions.');const health=A.collectionHealth({feed:notamFeed,request:notamRequest,start:v.windowStart,end:v.windowEnd});const manual=manualReview();if(!health.usable&&!manual.valid)issues.push('Airspace: '+health.message+' Or complete and record the independent official NOTAM briefing declaration.');if(el('notamterrain').value.trim()&&(!el('notamterrain').validity.valid||!el('notamterrainref').value.trim()))issues.push('Airspace: supply a valid highest terrain elevation and source, or clear the optional terrain filter.');for(const kind of ['uas','aip'])if((!feeds[kind]||el('date').value<feeds[kind].effectiveFrom||el('date').value>=feeds[kind].effectiveUntil)&&!manual.valid)issues.push('Airspace: '+kind.toUpperCase()+' reference layer missing/outside its effective cycle.');if(!navigator.onLine)issues.push('Airspace: offline — obtain fresh online briefing before GO.');return{issues,go:issues.length===0,source:feeds.uas?.source,issued:notamFeed?.issued,mirror:notamFeed?.mirror,missionRadius:v.radius,searchWindowStart:v.windowStart===null?null:new Date(v.windowStart).toISOString(),searchWindowEnd:v.windowEnd===null?null:new Date(v.windowEnd).toISOString(),briefingReference:el('briefingref').value,reviewed:el('airspacereviewed').checked,notamRequest:{...notamRequest},automatedNotamUsable:health.usable,manualNotam:manual,permissionsState:el('airspacepermissionstate').value,sessionEnd:Number.isFinite(v.end)?new Date(v.end).toISOString():null,sessionEndAssumed:v.assumedEnd,planningBufferMinutes:30,beforeFlightCheck,noticeChanges:noticeChangeState,heightMetresAGL:Number(el('height').value),highestTerrainMetresAMSL:el('notamterrain').value.trim()?Number(el('notamterrain').value):null,terrainReference:el('notamterrainref').value};};
